package com.mannaggia.app

import android.content.Context
import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.graphics.drawable.AnimationDrawable
import android.graphics.drawable.BitmapDrawable
import android.util.LruCache
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import java.security.MessageDigest

/**
 * Pixel-art saint portraits from assets/avatar/, generated by tools/ritratti/avatar.py.
 *
 * Each saint is `<sha1(name)[:12]>.png` (48x48), the same id as the audio files.
 * Legendary saints (assets/avatar/leggendari.txt) get an animated gold frame
 * (cornice_00..11.png) drawn on top.
 */
object Avatars {

    private const val DIR = "avatar"
    private const val FRAME_COUNT = 12
    /** 12 frames x 167 ms: one sparkle loop every 2 seconds. */
    private const val FRAME_MS = 167

    private val cache = LruCache<String, Bitmap>(300)

    @Volatile
    private var legendary: Set<String>? = null

    @Volatile
    private var frames: List<Bitmap>? = null

    /** Saint -> card number (1 = most famous), from catalogo.txt. */
    @Volatile
    private var numbers: Map<String, Int>? = null

    /** Same id as tools/tts/genera_audio.py and tools/ritratti/avatar.py. */
    fun fileId(saint: String): String =
        MessageDigest.getInstance("SHA-1").digest(saint.toByteArray(Charsets.UTF_8))
            .joinToString("") { "%02x".format(it) }.take(12)

    /** The saint's 48x48 portrait, or null if missing. */
    suspend fun load(context: Context, saint: String): Bitmap? = withContext(Dispatchers.IO) {
        cache.get(saint) ?: runCatching { decode(context, "${fileId(saint)}.png") }.getOrNull()
            ?.also { cache.put(saint, it) }
    }

    suspend fun isLegendary(context: Context, saint: String): Boolean = withContext(Dispatchers.IO) {
        val set = legendary ?: runCatching {
            context.applicationContext.assets.open("$DIR/leggendari.txt").bufferedReader(Charsets.UTF_8)
                .useLines { lines -> lines.map { it.trim() }.filter { it.isNotEmpty() && !it.startsWith("#") }.toSet() }
        }.getOrDefault(emptySet()).also { legendary = it }
        saint in set
    }

    /** Card number of [saint]: 1 is the most famous (and rarest to find among the famous). */
    suspend fun number(context: Context, saint: String): Int? = withContext(Dispatchers.IO) {
        val map = numbers ?: runCatching {
            context.applicationContext.assets.open("$DIR/catalogo.txt").bufferedReader(Charsets.UTF_8)
                .useLines { lines ->
                    lines.map { it.trim() }.filter { it.isNotEmpty() && !it.startsWith("#") }
                        .withIndex().associate { (i, s) -> s to i + 1 }
                }
        }.getOrDefault(emptyMap()).also { numbers = it }
        map[saint]
    }

    /** The pixel-art card binder icon of the main screen. */
    suspend fun binder(context: Context): BitmapDrawable? = icon(context, "raccoglitore.png")

    /** The pixel-art trophy cup (main screen, trophy list, unlock banner). */
    suspend fun cup(context: Context): BitmapDrawable? = icon(context, "coppa.png")

    /** Still silver frame of the special cards. */
    suspend fun silverFrame(context: Context): BitmapDrawable? = icon(context, "cornice_argento.png")

    /** The pixel-art saint-of-the-day icon (calendar page with a gold star). */
    suspend fun saintOfDayIcon(context: Context): BitmapDrawable? = icon(context, "santo_del_giorno.png")

    private suspend fun icon(context: Context, file: String): BitmapDrawable? = withContext(Dispatchers.IO) {
        runCatching { pixelated(context, decode(context, file)) }.getOrNull()
    }

    /** A new sparkling gold frame (each view needs its own; the bitmaps are shared). */
    suspend fun frameDrawable(context: Context): AnimationDrawable = withContext(Dispatchers.IO) {
        val bitmaps = frames ?: (0 until FRAME_COUNT).map { i -> decode(context, "cornice_%02d.png".format(i)) }
            .also { frames = it }
        AnimationDrawable().apply {
            for (b in bitmaps) addFrame(pixelated(context, b), FRAME_MS)
            isOneShot = false
        }
    }

    /** Scale up without smoothing, so the pixels stay crisp. */
    fun pixelated(context: Context, bitmap: Bitmap) =
        BitmapDrawable(context.resources, bitmap).apply { isFilterBitmap = false }

    private fun decode(context: Context, file: String): Bitmap =
        context.applicationContext.assets.open("$DIR/$file").use { input ->
            BitmapFactory.decodeStream(input, null, BitmapFactory.Options().apply { inScaled = false })
                ?: error("cannot decode $file")
        }
}
